(function(){var loadHandler=window['sl_{1EB086A2-055B-45E0-86A0-93FD4B2FFC8E}'];loadHandler&&loadHandler(32, '<div id="spr0_42d6a43"><div id="spr1_42d6a43" class="kern slide"><img id="img3_42d6a43" src="data:image/png;base64," width="1440px" height="810px" alt="" style="left:0px;top:0px;"/></div><div id="spr2_42d6a43" class="kern slide"><div id="spr3_42d6a43"><div id="spr4_42d6a43"><img id="img0_42d6a43" src="data:image/jpeg;base64," width="1440" height="810" alt=""/></div></div><div id="spr5_42d6a43" style="left:-241.002px;top:-223.214px;"><img id="img1_42d6a43" src="data:image/png;base64," width="859.893" height="1764.663" alt="" style="left:-1px;top:-1px;"/></div><div id="spr6_42d6a43" style="left:833.659px;top:-404.098px;"><div style="width:0px;"><span id="txt0_42d6a43" data-width="480.046875" style="top:-5.5px;">A Parcela Protegida Pernambucanas</span></div><div style="width:0px;"><span id="txt1_42d6a43" data-width="468.265625" style="top:32.5px;">é um seguro criado para proteger o</span></div><div style="width:0px;"><span id="txt2_42d6a43" data-width="475.203125" style="top:70.5px;">parcelamento da fatura, garantindo</span></div><div style="width:0px;"><span id="txt3_42d6a43" data-width="357.546875" style="top:108.5px;">mais segurança caso novos</span></div><div style="width:0px;"><span id="txt4_42d6a43" data-width="317.140625" style="top:146.5px;">imprevistos aconteçam.</span></div><div style="width:0px;"><span id="txt5_42d6a43" data-width="492.781250" style="top:222.5px;">O objetivo é simples: ajudar o cliente</span></div><div style="width:0px;"><span id="txt6_42d6a43" data-width="464.218750" style="top:260.5px;">a cumprir o acordo, mesmo se algo</span></div><div style="width:0px;"><span id="txt7_42d6a43" data-width="216.593750" style="top:298.5px;">sair do controle.</span></div></div><div id="spr7_42d6a43" style="left:50.909px;top:43.226px;"><div style="width:0px;"><span id="txt8_42d6a43" class="relpos" data-width="83.289032" style="top:-12.087px;">💡</span> <span id="txt9_42d6a43" class="relpos" data-width="230.568665" style="left:-0.005px;top:2.761px;"> DICAS </span> <span id="txt10_42d6a43" class="relpos" data-width="291.471313" style="left:-0.01px;top:2.761px;">DE OURO</span></div></div><div id="spr8_42d6a43" style="left:195.791px;top:152.791px;"><div id="svg6_42d6a43" style="left:0px;top:0px;"><svg width="1010" height="144" viewBox="0 0 1010 144"><g fill="none"><g><path fill="#132077" fill-opacity="0.698" d="M8.095,0 H1001.152 C1005.623,0 1009.247,3.143 1009.247,7.02 V136.721 C1009.247,140.598 1005.623,143.741 1001.152,143.741 H8.095 C5.949,143.741 3.889,143.001 2.371,141.685 C0.853,140.369 0,138.583 0,136.721 V7.02 C0,3.143 3.625,0 8.095,0 Z" fill-rule="evenodd"/></g></g></svg></div><div id="svg7_42d6a43" style="left:0px;top:0px;"><svg width="1010" height="144" viewBox="0 0 1010 144"><path fill="none" d="M0,0 h1009.247 v143.741 h-1009.247 Z"/></svg></div></div><div id="spr9_42d6a43" style="left:195.791px;top:314.886px;"><div id="svg11_42d6a43" style="left:0px;top:0px;"><svg width="1010" height="176" viewBox="0 0 1010 176"><g fill="none"><g><path fill="#132077" fill-opacity="0.698" d="M8.095,0 H1001.152 C1005.623,0 1009.247,3.092 1009.247,6.906 V168.594 C1009.247,172.408 1005.623,175.5 1001.152,175.5 H8.095 C3.625,175.5 0,172.408 0,168.594 V6.906 C0,3.092 3.625,0 8.095,0 Z" fill-rule="evenodd"/></g></g></svg></div><div id="svg12_42d6a43" style="left:0px;top:0px;"><svg width="1010" height="176" viewBox="0 0 1010 176"><path fill="none" d="M0,0 h1009.247 v175.5 h-1009.247 Z"/></svg></div></div><div id="spr10_42d6a43" style="left:195.791px;top:512.886px;"><div id="svg16_42d6a43" style="left:0px;top:0px;"><svg width="1010" height="146" viewBox="0 0 1010 146"><g fill="none"><g><path fill="#132077" fill-opacity="0.698" d="M7.866,0 H1001.381 C1003.467,0 1005.468,0.903 1006.943,2.512 C1008.418,4.12 1009.247,6.301 1009.247,8.576 V136.924 C1009.247,139.199 1008.418,141.38 1006.943,142.988 C1005.468,144.596 1003.467,145.5 1001.381,145.5 H7.866 C5.78,145.5 3.779,144.596 2.304,142.988 C0.829,141.38 0,139.199 0,136.924 V8.576 C0,6.301 0.829,4.12 2.304,2.512 C3.779,0.903 5.78,0 7.866,0 Z" fill-rule="evenodd"/></g></g></svg></div><div id="svg17_42d6a43" style="left:0px;top:0px;"><svg width="1010" height="146" viewBox="0 0 1010 146"><path fill="none" d="M0,0 h1009.247 v145.5 h-1009.247 Z"/></svg></div></div><div id="spr11_42d6a43" style="left:221.151px;top:165.874px;"><div style="width:0px;"><span id="txt11_42d6a43" data-width="230.300018" style="top:-5.04px;">Valide primeiro.</span></div><div style="width:0px;"><span id="txt12_42d6a43" data-width="557.144043" style="top:28.56px;">• “Entendo. Muita gente se sente assim.”</span></div><div style="width:0px;"><span id="txt13_42d6a43" data-width="520.547913" style="top:62.16px;">• “Faz sentido o que você tá dizendo.”</span></div><div style="width:0px;"><span id="txt14_42d6a43" data-width="511.728088" style="top:162.96px;">Use metáforas que geram empatia:</span></div><div style="width:0px;"><span id="txt15_42d6a43" data-width="888.384094" style="top:196.56px;">”É um passo simples agora, que evita um tombo maior depois.”</span></div><div style="width:0px;"><span id="txt16_42d6a43" data-width="907.032043" style="top:230.16px;">“É tipo um cinto de segurança: você espera não precisar, mas se</span></div><div style="width:0px;"><span id="txt17_42d6a43" data-width="268.295990" style="top:263.76px;">precisar, ele salva.”</span></div><div style="width:0px;"><span id="txt18_42d6a43" data-width="614.152100" style="top:364.56px;">Nunca pressione. Convide com suavidade:</span></div><div style="width:0px;"><span id="txt19_42d6a43" data-width="682.247986" style="top:398.16px;">“Você decide, mas achei importante te mostrar.”</span></div><div style="width:0px;"><span id="txt20_42d6a43" data-width="816.647949" style="top:431.76px;">“Se fizer sentido pra você, eu já incluo aqui com o acordo.”</span></div></div><div id="spr12_42d6a43" style="left:279.137px;top:719.893px;"><div id="spr13_42d6a43"><img id="img2_42d6a43" src="data:image/png;base64," width="895.247" height="49.373" alt=""/></div><div id="svg21_42d6a43" style="left:0px;top:0px;"><svg width="896" height="50" viewBox="0 0 896 50"><path fill="none" d="M0,0 h895.247 v49.373 h-895.247 Z"/></svg></div></div><div id="spr14_42d6a43" style="left:302.997px;top:719.893px;"><div style="width:0px;"><span id="txt21_42d6a43" data-width="864.444153" style="top:1.518px;">E lembre-se: a prioridade sempre será a quitação da dívida!</span></div></div></div></div>');})();